/**
 * Prints the shared colour blends. Called once, at the top of the page.
 */
function platinum_the_icon_defs() {
	$shapes = platinum_icon_shapes();
	echo '<svg class="ico-defs" width="0" height="0" aria-hidden="true" focusable="false"><defs>' . $shapes['defs'] . '</defs></svg>'; // phpcs:ignore WordPress.Security.EscapeOutput
}

/**
 * Returns one icon as inline SVG.
 *
 * @param string $name folder|disk|doc|cv|file|mail|notes|trash|music|terminal|pattern|puzzle|paint|mines|globe|window|mark|cel.
 * @return string
 */
function platinum_icon( $name ) {
	$shapes = platinum_icon_shapes();

	if ( 'defs' === $name || ! isset( $shapes[ $name ] ) ) {
		$name = 'doc';
	}

	return '<svg class="ico ico-' . esc_attr( $name ) . '" viewBox="0 0 32 32" width="32" height="32" aria-hidden="true" focusable="false">' . $shapes[ $name ] . '</svg>';
}
